head.script:
scwin.isIE = function() {
    var myNav = navigator.userAgent.toLowerCase();
    return (myNav.indexOf('msie') != -1) ? parseInt(myNav.split('msie')[1]) : false;
}
scwin.checkTextArea = function() {
    if (scwin.isIE() == 8) {
        return WebSquare.wUnit.getJq("#textarea1").val() == "setPlaceHolder";
    } else {
        return textarea1.getAttribute("placeholder") == "setPlaceHolder" && WebSquare.wUnit.getJq("#textarea1").val() == "setPlaceHolder";
    }
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 초기화면에 "setPlaceHolder"값이 보여지는지 확인한다.
    //1. After running the sample, check that the "setPlaceHolder" value is shown on the initial screen
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 1. "setPlaceHolder"값이 보여지는지 확인한다.(이전에는 초기화면에 "setPlaceHolder"값이 보여지지 않음)
    //1. Make sure that the "setPlaceHolder" value is shown (previously the "setPlaceHolder" value is not shown on the initial screen)
    WebSquare.wUnit.addCommand("assert", "scwin.checkTextArea()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    textarea1.setPlaceholder("setPlaceHolder");
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 14-Jun-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
